import{R as r,e as o,f as i,U as t}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Migrating from Freeform","description":"","frontmatter":{},"headers":[],"relativePath":"migrations/migrating-from-freeform.md","filePath":"migrations/migrating-from-freeform.md","lastUpdated":1775908585000}'),a={name:"migrations/migrating-from-freeform.md"};function n(l,e,m,s,f,d){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="migrating-from-freeform" tabindex="-1">Migrating from Freeform <a class="header-anchor" href="#migrating-from-freeform" aria-label="Permalink to &quot;Migrating from Freeform&quot;">​</a></h1><p>If your existing site has forms, submissions and email notifications from <a href="https://docs.solspace.com/craft/freeform/v5/" target="_blank" rel="noreferrer">Solspace Freeform</a>, it can be easily migrated over to Formie. Your existing content with Freeform will not be touched.</p><p>We support the following Freeform versions:</p><ul><li>Freeform 3.x</li><li>Freeform 4.x</li><li>Freeform 5.x</li></ul><p>To migrate your forms and form data, install Formie, and navigate to Formie → Settings → Migrations → Freeform. You&#39;ll need to have Freeform installed and enabled for this setting to appear.</p><p>You&#39;ll be shown a screen to select from any existing Freeform forms. Select which ones you want to migrate, and hit &quot;Migrate Forms&quot;. The next screen will show you the result of the migration, detailing what forms, email notifications and submissions were copied across and what errors or exceptions were encountered.</p><p>Any form that is attempted to be imported with the same handle will have a number affixed to the form. So if you already have a Formie form with a handle <code>contactForm</code> and also have a <code>contactForm</code> in Freeform, the migration tool will name this new form to <code>contactForm1</code>.</p><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><p>The following Freeform fields are currently unsupported in Formie:</p><ul><li>Payments fields (Pro)</li><li>Opinion Scale Field (Pro)</li><li>Rating Field (Pro)</li><li>Regex Field (Pro)</li><li>Rich Text Field (Pro)</li><li>Dynamic Recipient Field</li><li>Mailing List Field</li><li>Recaptcha Field</li></ul>',10)])])}const h=r(a,[["render",n]]);export{p as __pageData,h as default};
